%[text] # BEV System Model - Simulation Case
modelName = "BEV_system_model";
load_system(modelName)
BEV_useBasic %[output:09c0e256]
VehSpdRef_loadCase_Constant( ... %[output:group:6087eed0] %[output:2589cf2e]
  ModelName = modelName, ... %[output:2589cf2e]
  TargetSubsystemPath = "/Controller & Environment/Vehicle speed reference") %[output:group:6087eed0] %[output:2589cf2e]
simOut = sim(modelName);
simData = extractTimetable(simOut.logsout);
fig = BEV_ResultsCompactPlot(SimData = simData, PlotTemperature = false); %[output:3c4bdad6]
